// runtime/telemetry/events/kv_cache_event_v2.h
enum class CacheOutcome : uint8_t { kHit = 0, kMiss = 1, kPartial = 2 };

struct KvCacheEventV2 {
  CacheOutcome outcome;
  uint32_t requested_prefill_tokens;
  uint32_t cached_prefill_tokens;
  uint64_t hit_bytes_estimate;
  float saved_prefill_ms_estimate;
  uint32_t lookup_count;
  uint32_t insert_count;
  uint32_t evict_count;
  uint64_t prefix_bucket;  // hash bucket (not raw prefix)
  bool classifier_clamped;
  uint8_t attempt_index;
  bool is_retry;
  std::string_view cache_namespace;
  std::string_view model_runtime_id;
};

inline CacheOutcome ClassifyOutcome(uint32_t requested, uint32_t cached) {
  if (requested == 0) return CacheOutcome::kMiss;
  if (cached == 0) return CacheOutcome::kMiss;
  if (cached >= requested) return CacheOutcome::kHit;
  return CacheOutcome::kPartial;
}
